package com.gymmind.knowledge.api; import com.gymmind.knowledge.application.*; import com.gymmind.ai.domain.ContextSegment; import com.gymmind.shared.api.ApiResponse; import com.gymmind.shared.security.CurrentActorProvider; import org.springframework.web.bind.annotation.*; import java.util.List; @RestController @RequestMapping("/api/v1/knowledge") public class KnowledgeSearchController {private final KnowledgeSearchService service;private final CurrentActorProvider actors;public KnowledgeSearchController(KnowledgeSearchService s,CurrentActorProvider a){service=s;actors=a;} @GetMapping("/search") public ApiResponse<List<ContextSegment>> search(@RequestParam String q){return ApiResponse.success(service.search(actors.requireCurrent(),q));}}
